			compared = Byte.compare(rows.planes[leftOrdinal], rows.planes[rightOrdinal]);
			for (int component = 0; compared == 0 && component < FrontierOmniLayout.COMPONENT_COUNT; component++) {
				compared = Long.compare(rows.components[component][leftOrdinal],
						rows.components[component][rightOrdinal]);
			}
			return compared;
